def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # If we're at the end of the line, add the current field
        if i == len(line):
            fields.append("")
            break

        # Check if this field is quoted
        if i < len(line) and line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the end of the field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote character
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i == len(line):
                            fields.append(field)
                            break
                        elif i < len(line) and line[i] == ',':
                            fields.append(field)
                            i += 1
                            # If we just consumed the last comma, add empty field
                            if i == len(line):
                                fields.append("")
                            break
                        else:
                            # Invalid: closing quote not followed by comma or EOL
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # We exited the while loop without breaking - unterminated quoted field
                return None
        else:
            # Unquoted field - runs to next comma
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain a double quote
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1
                # If we just consumed the last comma, add empty field
                if i == len(line):
                    fields.append("")

    return fields

